d = data if isinstance(data, dict) else {}
raw_items = d.get("items")
if not isinstance(raw_items, list):
    raw_items = []
field = str(d.get("field") or "").replace("\r", " ").replace("\n", " ").strip()
try:
    capn = int(cap or 12)
except Exception:
    capn = 12
if capn < 1:
